import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.map.js";
import { get_inventory_items } from "@/mixins/GetInventoryItems.js";
import { edit_user_app_access } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  name: "EditMemberDialog",
  mixins: [get_inventory_items],
  props: {
    dialog: {
      type: Boolean,
      default: false
    },
    memberData: {
      type: Object,
      default: () => ({})
    },
    dashboardId: {
      type: String,
      default: ""
    }
  },
  data() {
    return {
      loading: false,
      localMemberData: {
        client_id: "",
        products: [],
        subscriber_id: ""
      }
    };
  },
  computed: {
    isValidMember() {
      return this.localMemberData.products && this.localMemberData.products.length > 0;
    },
    productOptions() {
      return this.masterItems.map(item => ({
        text: item.item_name,
        value: item.item_id
      }));
    }
  },
  methods: {
    fetch_product_name(products) {
      return this.productOptions.filter(item => products.includes(item.value)).map(item => item.text);
    },
    async confirm() {
      if (this.isValidMember) {
        this.loading = true;
        try {
          // Simulate API call delay
          let result = await API.graphql(graphqlOperation(edit_user_app_access, {
            input: {
              action_type: "EDIT",
              dashboard_id: this.dashboardId,
              products: this.localMemberData.products,
              products_name: this.fetch_product_name(this.localMemberData.products),
              user_email_id: this.memberData.client_id,
              subscriber_id: this.memberData.subscriber_id
            }
          }));
          var response = JSON.parse(result.data.edit_user_app_access);
          if (response.Status == "SUCCESS") {
            this.$emit("successMsg", response.Message);
          } else {
            this.$emit("errorMsg", response.Message);
          }
          // Emit success message
          // this.$emit("successMsg", `Products updated successfully!`);

          this.resetForm();
        } catch (error) {
          this.$emit("errorMsg", "Failed to update products. Please try again.");
        } finally {
          this.loading = false;
        }
      } else {
        this.$emit("errorMsg", "Please select at least one product.");
      }
    },
    cancel() {
      this.$emit("cancel");
      this.resetForm();
    },
    resetForm() {
      this.localMemberData = {
        client_id: "",
        products: [],
        subscriber_id: ""
      };
    },
    initializeData() {
      if (this.memberData && Object.keys(this.memberData).length > 0) {
        // Handle multiple products - convert single product to array or use existing array
        let products = [];
        if (this.memberData.products && Array.isArray(this.memberData.products)) {
          products = this.memberData.products;
        } else if (this.memberData.product || this.memberData.app_name || this.memberData.service_name || this.memberData.subscriber_id) {
          products = [this.memberData.product || this.memberData.app_name || this.memberData.service_name || this.memberData.subscriber_id];
        }
        this.localMemberData = {
          client_id: this.memberData.client_id || this.memberData.name || this.memberData.user_name || "",
          products: products,
          subscriber_id: this.memberData.subscriber_id || ""
        };
      }
    }
  },
  watch: {
    dialog(newVal) {
      if (newVal) {
        this.initializeData();
      }
    },
    memberData: {
      handler() {
        this.initializeData();
      },
      deep: true
    }
  },
  created() {
    // Fetch inventory items when component is created
    this.get_inventory_items();
  }
};
